import pandas as pd


def _is_null(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or v is pd.NaT or pd.isna(v)


def _changed(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_product = inputs["DIM_PRODUCT"]
    stg_product = inputs["STG_PRODUCT"]

    # Build mutable list of dict rows from existing DIM_PRODUCT
    rows = []
    for _, r in dim_product.iterrows():
        rows.append({
            "product_id": r["product_id"],
            "category": r["category"],
            "price_band": r["price_band"],
            "eff_start_date": r["eff_start_date"],
            "eff_end_date": r["eff_end_date"],
            "is_current": r["is_current"],
        })

    # Map product_id -> index of current row (is_current == 1), if any
    current_idx = {}
    for idx, row in enumerate(rows):
        if row["is_current"] == 1:
            current_idx[row["product_id"]] = idx

    # Sort staged records by product_id, update_date ascending
    stg_sorted = stg_product.sort_values(
        by=["product_id", "update_date"], ascending=[True, True], kind="mergesort"
    )

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_cat = s["category"]
        s_price = s["price_band"]
        s_date = s["update_date"]

        idx = current_idx.get(pid, None)

        if idx is None:
            new_row = {
                "product_id": pid,
                "category": s_cat,
                "price_band": s_price,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_idx[pid] = len(rows) - 1
        else:
            c = rows[idx]
            if _changed(c["category"], s_cat) or _changed(c["price_band"], s_price):
                # expire current row
                rows[idx]["eff_end_date"] = s_date
                rows[idx]["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_cat,
                    "price_band": s_price,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_idx[pid] = len(rows) - 1
            # else: no-op, unchanged record

    out_df = pd.DataFrame(
        rows,
        columns=[
            "product_id",
            "category",
            "price_band",
            "eff_start_date",
            "eff_end_date",
            "is_current",
        ],
    )

    return {"dim_product_out": out_df}
